
CREATE TABLE "warn_table" (
  "name" VARCHAR2(32) NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tag" VARCHAR2(255) NOT NULL,
  "count" NUMBER(10) NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "id" NUMBER(10) NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "balance" NUMBER(16, 2) NOT NULL
);
